/* stand-in for SweetAlert2 v8 (testing / preview only): Swal.fire(options) → Promise<{value}> with a simple dialog */
(function(){
function fire(o,t,i){ if(typeof o==='string'){o={title:o,text:t,type:i}} o=o||{};
  return new Promise(function(done){
    var w=document.createElement('div'); w.className='swal2-container'; w.setAttribute('role','dialog'); w.setAttribute('aria-modal','true');
    w.style.cssText='position:fixed;inset:0;z-index:20000;background:rgba(16,38,63,.45);display:flex;align-items:center;justify-content:center;padding:16px';
    var b=document.createElement('div'); b.className='swal2-popup'; b.style.cssText='background:#fff;border-radius:14px;max-width:420px;width:100%;padding:24px;text-align:center;font-family:inherit';
    var h=document.createElement('h2'); h.className='swal2-title'; h.style.cssText='font-size:19px;font-weight:800;margin:0 0 8px'; h.textContent=o.title||'';
    var p=document.createElement('div'); p.className='swal2-content'; p.style.cssText='font-size:15px;color:#4a5a6c;margin-bottom:18px'; if(o.html && o.html.nodeType){p.appendChild(o.html)}else if(o.html){p.innerHTML=o.html}else{p.textContent=o.text||''}
    var r=document.createElement('div'); r.className='swal2-actions'; r.style.cssText='display:flex;gap:10px;justify-content:center;flex-wrap:wrap';
    function btn(cls,label,val){var x=document.createElement('button'); x.type='button'; x.className=cls; x.innerHTML=label; x.onclick=function(){w.remove(); done(val)}; r.appendChild(x); return x}
    var ok=btn('swal2-confirm '+(o.confirmButtonClass||'btn btn-primary'), o.confirmButtonText||'OK', {value:true});
    if(o.showCancelButton){btn('swal2-cancel '+(o.cancelButtonClass||'btn btn-danger'), o.cancelButtonText||'Cancel', {dismiss:'cancel'})}
    b.appendChild(h); b.appendChild(p); b.appendChild(r); w.appendChild(b); document.body.appendChild(w); ok.focus();
    if(o.timer){setTimeout(function(){if(w.parentNode){w.remove(); done({dismiss:'timer'})}},o.timer)}
  });
}
window.Swal=window.swal=window.Sweetalert2={fire:fire,DismissReason:{timer:'timer',cancel:'cancel'},close:function(){var w=document.querySelector('.swal2-container'); if(w){w.remove()}},showLoading:function(){},getContent:function(){return document.querySelector('.swal2-content')},getTimerLeft:function(){return 0}};
})();
